_srixon_item.body:
// Newest-first scan (cap 4) for the latest Srixon ball; capture its product URL.
const orders = (Array.isArray(ctx.orders) ? ctx.orders : []).slice()
  .sort((a, b) => new Date(b.date) - new Date(a.date));
let scanned = 0;
for (const o of orders) {
  if (!o || !o.href) continue;
  if (scanned++ >= 4) break;
  let items = [];
  try {
    const r = await h.parse(await h.fetchText(o.href));
    const data = r && r.data;
    items = (data && data.order && Array.isArray(data.order.items)) ? data.order.items : [];
  } catch (e) { continue; }
  const hits = items.filter(it => /srixon/i.test(it.name || '') && /golf ball/i.test(it.name || ''));
  if (hits.length) {
    let best = hits[0];
    for (const it of hits) if ((h.parseNumber(it.lineTotal) || 0) > (h.parseNumber(best.lineTotal) || 0)) best = it;
    return { name: best.name, url: best.url || '', order: o.number, href: o.href, date: o.date };
  }
}
return null;

last_item.body:
let n = String((vars._srixon_item && vars._srixon_item.name) || '');
if (!n) return '';
n = n.split(/ [-–] /)[0];
n = n.replace(/custom logo/ig, '').replace(/double dozen/ig, '').replace(/  +/g, ' ');
return n.trim();

reorder_url.body:
const it = vars._srixon_item;
if (it && it.url) return it.url;
if (it && it.href) return it.href;
return '';

srixon_line.body:
const it = vars._srixon_item;
if (!it) return '';
const name = vars.last_item || it.name;
const link = it.url ? ('<a href="' + it.url + '">' + name + '</a>') : name;
return 'I saw the ' + link + ' on your account from last time — those are included in this deal too, so it is an easy one to restock.';

logo_ps.body:
const p = (ctx.proofs && ctx.proofs[0]) || null;
if (!p || !p.id) return '';
return 'And good news — we still have your logo on file, so this can be a quick reorder.';

logo_links.body:
const p = (ctx.proofs && ctx.proofs[0]) || null;
if (!p || !p.id) return '';
const it = vars._srixon_item;
const reorder = (it && it.url) ? it.url : (it && it.href) ? it.href : '';
const parts = [];
if (reorder) parts.push('<a href="' + reorder + '">reorder your last order</a>');
if (p.instant_mockup) parts.push('<a href="' + p.instant_mockup + '">see your logo on a ball</a>');
if (p.apparel_mockup) parts.push('<a href="' + p.apparel_mockup + '">on apparel</a>');
if (!parts.length) return '';
return 'Quick links: ' + parts.join(' &middot; ') + '.';

days_left.body:
const end = new Date(vars.promo_end);
if (isNaN(end.getTime())) return '';
const now = new Date();
end.setHours(0, 0, 0, 0); now.setHours(0, 0, 0, 0);
const d = Math.round((end.getTime() - now.getTime()) / 86400000);
if (d < 0) return '';
if (d === 0) return 'just today';
return d === 1 ? '1 more day' : (d + ' more days');

